INSERT INTO `movies` VALUES (1,'Án Mạng Karaoke','an-mang-karaoke','Một người hàng xóm mê hát karaoke bất ngờ bị sát hại trong căn homestay thiền biệt lập trên núi, khiến chuyến hành hương của một xóm nhỏ bị biến thành trò chơi đấu trí bất đắc dĩ. Phim có suất chiếu sớm ngày 21/10/2026 và khởi chiếu chính thức ngày 30/10/2026.','Hoàng Lê','Vân Dung, Đoàn Thiên Ân, Đại Nghĩa',96,'2026-10-30','2026-12-25','T16','posters/an-mang-karaoke-1.webp','https://www.youtube.com/watch?v=SpBeFk9L7yY','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(2,'Trại Buôn Người','trai-buon-nguoi','Vì cứu em gái sa bẫy buôn người ở vùng biên giới, Ny (Steven Nguyễn) cùng bạn thân bị bắt làm nô dịch trong sào huyệt lừa đảo tàn bạo. Tại đây, họ cùng các trinh sát nằm vùng và các nạn nhân hứng chịu bi kịch thể xác âm thầm lập kế hoạch trốn thoát.','Toni Dương Bảo Anh','Steven Nguyễn, Quách Ngọc Ngoan, Huỳnh Minh Kiên',135,'2026-09-25','2026-11-20','T18','posters/trai-buon-nguoi.webp','https://www.youtube.com/watch?v=3uzzMdKQImk','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(3,'Quỷ Ăn Tạng 4: Hổ Tinh','quy-an-tang-4-ho-tinh','Phim đưa khán giả trở về thời điểm Yak (Nadech Kugimiya thủ vai) lần đầu gặp Trung sĩ Paphan (Ongart Cheamcharoenpornkul thủ vai), khi cả hai cùng tham gia nhiệm vụ nguy hiểm nhằm tìm kiếm tiểu đội tình báo mất tích giữa khu rừng bí ẩn. Dẫn đầu đội tìm kiếm tiến sâu vào rừng, Yak và Trung sĩ Paphan bất ngờ chạm trán Hổ Tinh - sinh vật siêu nhiên mang hình hài mãnh thú, chuyên săn và ăn thịt người, đồng thời có khả năng biến hóa thành nhiều hình dạng để thao túng con mồi. Trước mối đe dọa chưa từng đối mặt, cả hai buộc phải hợp tác chiến đấu và sinh tồn, đồng thời tìm ra bí mật ẩn sâu trong khu rừng trước khi trở thành những nạn nhân tiếp theo.','Narit Yuvaboon, Thanadet Pradit, Chalit Krileadmongkon','Nadech Kugimiya, Ong-art Cheamcharoenpornkul, Maylada Susri, Wichapas Sumettikul, Sahajak Boonthanakit, Akarin Akaranitimaytharatt, Dan Chupong, Chanintorn Jitpreeda, Natthachai Sirinanthachot, Pavarit Mongkolpisit',111,'2026-10-16','2026-12-11','T18','posters/quy-an-tang-4-ho-tinh.webp','https://www.youtube.com/watch?v=rpFS0tXzVro','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(4,'Cõi Nguyền','coi-nguyen','Dựa trên loạt truyền thuyết đô thị gây chấn động Nhật Bản, Cõi Nguyền bắt nguồn từ lời nguyền của một người phụ nữ kỳ bí đã ám cô gái trẻ tên Riko chỉ với một dòng tin nhắn: “Tất cả mọi người đều đáng chết”. Kể từ thời khắc lời nguyền linh ứng, lần lượt tất cả những người bạn xung quanh Riko đều chết một cách bí ẩn và các vụ án mạng đều được đưa ra kết luận với nguyên nhân tử vong là “tự sát”. Tuy nhiên, điều kinh hoàng hơn là số lượng những vụ án mạng ngày một gia tăng khiến Riko phải tự mình lao vào vòng xoáy chết chóc để lý giải “Cõi Nguyền” rốt cuộc được gieo rắc từ đâu và làm cách nào để bản thân không trở thành nạn nhân tiếp theo.','Ken\'ichi Ugana','Yukino Kaizu, YU, Yutaka Kyan, Tammy Lin, Mimi Shao, Ray Fan, Mondo Otani, Chen Wan-hao, Yuhei Shirakawa, Raion Yoza, Shiho, 艾瑪, Reika Oozeki, Hironobu Nomura, Yasukaze Motomiya',89,'2026-10-23','2026-12-18','T18','posters/coi-nguyen.webp','https://www.youtube.com/watch?v=zsMuQUkduug','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(5,'Oán Linh Đòi Mạng','oan-linh-doi-mang','Phim xoay quanh câu chuyện của gia đình Tomy (Andri Mashadi). Với mong muốn mang lại một cuộc sống tốt đẹp hơn cho vợ (Titi Kamal) và các con, Tomy quyết định gánh một khoản vay thế chấp lớn để mua căn nhà trong mơ tại khu phức hợp dân cư cao cấp mang tên Perumahan Laddaland.\n\nTuy nhiên, niềm vui chưa kéo dài được bao lâu thì hàng loạt hiện tượng rùng rợn xảy ra. Bắt đầu từ cái chết bất thường của người giúp việc trong nhà, những âm thanh kỳ lạ, các bóng ma ám ảnh xuất hiện dày đặc, cùng với những bí mật đen tối dần hé lộ đằng sau khu dân cư này. Khi các hộ gia đình khác lần lượt hoảng sợ tìm cách dọn đi, gia đình Tomy lại rơi vào thế kẹt buộc phải tìm cách sinh tồn giữa chốn ác mộng.','Awi Suryadi','Titi Kamal, Andri Mashadi, Anantya Rezky Kirana, Shakeel Fauzi Aisy, Delia Husein, Aufa Assagaf, Laras Sardi, Raffan Al Aryan, Adjis Doaibu, Arief Didu, Sri Yatun, Sarah Tumiwa, Zidni Hakim, Kiky Drajat, Farah Ramadhani, Callysta Novela, Jonathan Alvaro',98,'2026-10-23','2026-12-18','T18','posters/oan-linh-doi-mang.webp','https://www.youtube.com/watch?v=ycdsf8OuqY0','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(6,'Bambi: Lãnh Địa Săn Mồi','bambi-lanh-dia-san-moi','Bộ phim kể về Bambi, một chú nai bị đột biến sau khi nai mẹ bị thợ săn sát hại và môi trường sống bị ô nhiễm nghiêm trọng. Trở thành một sinh vật khổng lồ và hung dữ, Bambi bắt đầu hành trình trả thù con người. Câu chuyện xoay quanh một người mẹ và con trai bị mắc kẹt giữa khu rừng, nơi họ trở thành con mồi của sinh vật đáng sợ này.','Dan Allen','Roxanne McKee, Tom Mulheron, Adrian Relph, Nicola Wright, Alex Cooke, Ewan Borthwick, Big Tobz, Joseph Greenwood, Russell Geoffrey Banks, Samira Mighty, Catherine Adams, Luke Cavendish, David Ambler',80,'2026-10-23','2026-12-18','T16','posters/bambi-lanh-dia-san-moi.webp','https://www.youtube.com/watch?v=_6mbpOiCWw0','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(7,'Shaun the Sheep: Quái Lạ Ghé Nhà','shaun-the-sheep-quai-la-ghe-nha','Shaun the Sheep: Quái Lạ Ghé Nhà bắt đầu với sự cố Ông chủ vô tình phá hỏng vườn bí ngô mà đàn cừu đang chuẩn bị cho Halloween. Để cứu vãn tình hình, Shaun trổ tài làm “nhà khoa học”, nhưng thí nghiệm lại kéo theo hàng loạt rắc rối ngoài dự tính. Khi Ông chủ mất tích và một sinh vật bí ẩn xuất hiện trong rừng, cả đàn cừu lên đường tìm kiếm Ông chủ và đối mặt với một chuyến phiêu lưu vừa quái vừa nhộn.','Steve Cox, Matthew Walker','Justin Fletcher, John Sparkes, Nina Sosanya, Kate Harbour, Andy Nyman, Simon Greenall, Emma Tate, Rich Webber, Paul Whitehouse, Roman Kemp, Dani Dyer, Chris Morrell, Matthew Walker, Steve Cox',81,'2026-10-16','2026-12-11','P','posters/shaun-the-sheep-quai-la-ghe-nha.webp','https://www.youtube.com/watch?v=8q6XZq8a0iA','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(8,'Bí Mật Bị Chôn Vùi','bi-mat-bi-chon-vui','Bí Mật Bị Chôn Vùi (Verity) được chuyển thể từ cuốn tiểu thuyết bán chạy nhất của Colleen Hoover. Bộ phim giật gân tâm lý đầy lôi cuốn này xoay quanh nữ nhà văn nổi tiếng Verity Crawford (Anne Hathaway). Lowen Ashleigh (Dakota Johnson) - nhà văn đang chật vật với sự nghiệp, được mời đến dinh thự hẻo lánh Crawford để viết thay. Tại đây, Lowen phát hiện những ghi chép ám ảnh, hé lộ những bí mật gây sốc về chồng Verity, Jeremy (Josh Hartnett), khiến cô dần lạc lối giữa hư cấu và thực tại, giữa thao túng và sức hút , cũng như giữa cơ hội và sự ám ảnh.','Michael Showalter','Dakota Johnson, Anne Hathaway, Josh Hartnett, Ismael Cruz Cordova, Brady Wagner, Irina Dvorovenko, K.K. Moggie, Michael Abbott Jr., Alex Cooper',117,'2026-10-16','2026-12-11','T18','posters/bi-mat-bi-chon-vui.webp','https://www.youtube.com/watch?v=wBAco9LJ4To','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(9,'Street Fighter','street-fighter','Lấy bối cảnh năm 1993, Ryu và Ken, hai đấu sĩ từng xa cách bị kéo trở lại chiến đấu khi Chun-Li chiêu mộ họ tham gia giải Chiến Binh Thế Giới đầy khốc liệt. Nhưng đằng sau đó là một âm mưu chết chóc, buộc họ phải đối đầu với nhau và quá khứ của chính mình, nếu không tất cả sẽ CHẤM HẾT! Dưới sự chỉ đạo của đạo diễn Kitao Sakurai, Street Fighter mang những trận chiến game thùng lên màn ảnh rộng với các đòn thế quen thuộc cùng dàn nhân vật được yêu thích.','Kitao Sakurai','Noah Centineo, Andrew Koji, Callina Liang, Joe Anoa\'i, David Dastmalchian, Cody Rhodes, Andrew Schulz, Eric André, Vidyut Jammwal, Orville Peck, Olivier Richters, Hirooki Goto, Rayna Vallandingham, Alexander Volkanovski, 50 Cent, Jason Momoa',119,'2026-10-16','2026-12-11','T16','posters/street-fighter.webp','https://www.youtube.com/watch?v=xwnZ_uvrFs0','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(10,'Án Mạng Xém Hoàn Hảo','an-mang-xem-hoan-hao','Trinh, cô nàng TikToker ngôn tình triệu view, tỉnh dậy giữa phim trường lạnh lẽo với cái đầu đau như búa bổ, mất trí nhớ và phát hiện xác của Yến (diễn viên) – tình địch đang bị nghi ngờ có gì mờ ám với diễn viên Khang (chồng sắp cưới). Đại (thám tử) được Trinh thuê theo dõi vụ ngoại tình lẻn vào giúp thì vấp ngã để lại dấu vân tay lên tử thi và vô tình bị bảo vệ bắt quả tang. Kể từ đây, liên tiếp những tình huống oái oăm mà cặp đôi “đũa lệch” phải đối mặt: chạy trốn khỏi cảnh sát dí sát gót và sát thủ rình rập, vừa cãi nhau tóe khói vừa phá án. Song Song đó, cả hai vô tình lật tẩy bí mật động trời của showbiz','Đức Nguyễn','Anh Tú Atus, DJ Mie, Vũ Ngọc Anh, Huy Khánh, Long Đẹp Trai, Sỹ Toàn',124,'2026-10-09','2026-12-04','T18','posters/an-mang-xem-hoan-hao.webp','https://www.youtube.com/watch?v=IW-k9cMySWg','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(11,'Cá Voi Nuốt Chửng','ca-voi-nuot-chung','Câu chuyện kể về một thợ lặn, trong khi tìm kiếm hài cốt cha mình, đã bị một con cá voi nhà táng khổng lồ dài 24 mét, nặng 27 tấn nuốt chửng và chỉ có một giờ để thoát ra trước khi hết oxy.','Bronte Higgs',NULL,106,'2026-10-16','2026-12-11','T13','posters/ca-voi-nuot-chung.webp','https://www.youtube.com/watch?v=CyoPI-UK9hw','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(12,'Người Mẹ Khác','nguoi-me-khac','Người Mẹ Khác theo chân Bela, cô bé 8 tuổi đang phải chứng kiến cuộc hôn nhân của cha mẹ dần tan vỡ. Giữa bầu không khí căng thẳng trong gia đình, một thực thể bí ẩn xuất hiện từ chiếc tủ quần áo trong phòng ngủ và bắt đầu ám ảnh cả ngôi nhà. Bela gọi nó là \"Người Mẹ Khác\", bởi sinh vật ấy mang gương mặt giống hệt mẹ ruột của mình. Khi ranh giới giữa người thân và thế lực tà ác dần bị xóa nhòa, cô bé buộc phải đối mặt với cơn ác mộng kinh hoàng ngay trong chính ngôi nhà của mình.','Rob Savage','Jessica Chastain, Arabella Olivia Clark, Jay Duplass, Dichen Lachman, Arian Moayed, Karen Allen, Sean Kaufman, Adam Silver, Carrie Dimaculangan, Travis Nelson, Hayley Spelman, Rosie Anne O\'Gorman, Alejandro Nieves, Tyrone Kearns, Eleanor Jordan O\'Farrell',93,'2026-10-09','2026-12-04','T18','posters/nguoi-me-khac.webp','https://www.youtube.com/watch?v=8qy8tHRKQoA','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(13,'Blue Lock: Cuộc Chiến Của Những Tiền Đạo','blue-lock-cuoc-chien-cua-nhung-tien-dao','Nội Dung Phim Theo chân 300 cầu thủ bóng đá trung học tham gia những vòng tuyển chọn khắc nghiệt tại một cơ sở huấn luyện bí mật, nơi chỉ một người duy nhất có thể vươn lên trở thành tiền đạo xuất sắc nhất thế giới, còn những người bị loại sẽ bị cấm thi đấu cho Đội tuyển Quốc gia Nhật Bản. Bộ truyện tranh bán chạy hàng đầu Blue Lock được chuyển thể thành Live action.','Yusuke Taki','Fumiya Takahashi, Kaito Sakurai, Kyohei Takahashi, Kouta Nomura, Yuzu Aoki, Sho Nishigaki, Yuki Tachibana, Raizou Ishikawa, Joey Iwanaga, Shunya Asano, Sakurai Yuki, Kura Yuki, K, Keito Tsuna, Kouhei Higuchi, Sousyo Tomimoto, Keisuke Kida, Ryota Miura',127,'2026-10-09','2026-12-04','P','posters/blue-lock-cuoc-chien-cua-nhung-tien-dao.webp','https://www.youtube.com/watch?v=9spa9_P9dRY','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(14,'Trái Tim Quái Thú','trai-tim-quai-thu','Sau một vụ tai nạn máy bay kinh hoàng, sĩ quan Lực lượng Đặc nhiệm James Belmont (Brad Pitt) và chú chó chiến đấu Odin bị mắc kẹt giữa vùng hoang dã sâu thẳm của Alaska. Từ đó, họ buộc phải cùng nhau bước vào cuộc chiến sinh tồn khốc liệt trước thiên nhiên khắc nghiệt. Từ đạo diễn danh tiếng David Ayer, Trái Tim Quái Thú là một bộ phim phiêu lưu đầy căng thẳng, khai thác mối gắn kết không thể tách rời giữa một người đàn ông và người bạn thân thiết nhất của mình, khi cả hai phải đối mặt với trận chiến lớn nhất cuộc đời.','David Ayer','Brad Pitt, J.K. Simmons, Anna Lambe',101,'2026-10-02','2026-11-27','T13','posters/trai-tim-quai-thu.webp','https://www.youtube.com/watch?v=IfhO5CJ8BVM','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(15,'Scotty Giải Cứu Hoàng Thượng','scotty-giai-cuu-hoang-thuong','Scotty - một chú mèo hoang vốn quen sống trong lãnh địa của mình bất ngờ bị kéo vào cuộc phiêu lưu bất đắc dĩ cùng Katie, một cô mèo nhà. Đến từ hai thế giới khác biệt, Boss hạng sang và Mèo hạng xoàng học cách cùng nhau vượt qua muôn vàn hiểm nguy. Sau hành trình ấy, cả hai dần gắn kết và hiểu được ý nghĩa thật sự của nơi gọi là nhà.','Mohammad Pirzadi','William Hope, Stuart Milligan, Phil Cornwell, Walles Hamonde, Jay Rincon, Dario Coates, Penelope Rawlins, George Naylor, Jessica Claire Preddy, Adam Diggle, Lizzie Wofford, Joe Jameson',80,'2026-10-02','2026-11-27','P','posters/scotty-giai-cuu-hoang-thuong.webp','https://www.youtube.com/watch?v=yqYjXjDDthY','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(16,'Quyết Cua Anh Này','quyet-cua-anh-nay','Henry là một anh chàng tốt bụng, yêu động vật nhưng mắc một căn bệnh kỳ lạ: cứ mỗi sáng thức dậy, anh lại chẳng nhớ gì về những chuyện đã xảy ra ngày hôm trước. Hãy cùng đón xem câu chuyện Lucy làm quen Henry lại mỗi ngày.','Mez Tharatorn','Nadech Kugimiya, Minnie, Kiat Kitjaroen, Arthit Somnoi, Tipargon Chaiprasit',115,'2026-10-02','2026-11-27','T13','posters/quyet-cua-anh-nay.webp','https://www.youtube.com/watch?v=XKdEiTx9W68','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(17,'Avengers: Hồi Kết - Phiên Bản Đặc Biệt','avengers-hoi-ket-phien-ban-dac-biet','Phần kết hoành tráng của Infinity Saga sẽ trở lại rạp chiếu với Avengers: Hồi Kết - Phiên Bản Đặc Biệt vào ngày 25/09/2026. Sau những sự kiện thảm khốc khiến một nửa dân số thế giới biến mất, những người hùng còn lại phải vật lộn để tiếp tục cuộc sống. Cuối cùng, họ buộc phải hợp sức để khôi phục trật tự và sự cân bằng cho vũ trụ, đồng thời đưa những người thân yêu trở về trong cuộc đối đầu đầy kịch tính với Thanos.','Joe Russo, Anthony Russo','Josh Brolin, Chris Pratt, Robert Downey Jr., Chris Hemsworth, Tom Hiddleston, Chris Evans, Mark Ruffalo, Benedict Cumberbatch, Samuel L. Jackson, Vin Diesel, Bradley Cooper, Dave Bautista, Zoe Saldana, Karen Gillan, Scarlett Johansson, Jeremy Renner',183,'2026-09-25','2026-11-20','T13','posters/avengers-4-endgame.webp','https://www.youtube.com/watch?v=xpfuRa6bzVo','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(18,'Pháo Hoa Lúc Bình Minh','phao-hoa-luc-binh-minh','Bộ phim hoạt hình Pháo Hoa Lúc Bình Minh (A New Dawn) kể về hành trình trưởng thành của ba người trẻ tìm cách đối diện với quá khứ và tương lai khi xưởng pháo hoa truyền thống Obinata hơn 300 năm tuổi của gia đình đứng trước nguy cơ bị xóa sổ.','Yoshitoshi Shinomiya','Riku Hagiwara, Kotone Furukawa, Miyu Irino, Takashi Okabe',75,'2026-09-25','2026-11-20','P','posters/phao-hoa-luc-binh-minh.webp','https://www.youtube.com/watch?v=oXudBJeF1TI','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(19,'Vùng Đất Quỷ Dữ 2026','vung-dat-quy-du-2026','Một phiên bản Resident Evil mới trở lại đầy kịch tính và kinh hoàng từ bộ óc quái kiệt của đạo diễn Zach Cregger đứng sau “Weapons” & “Barbarian”. Với cốt truyện hoàn toàn mới, phim xoay quanh Bryan (Austin Abrams), một nhân viên vận chuyển vật tư y tế vô tình bị cuốn vào cuộc chạy đua sinh tồn nghẹt thở và dồn dập trong một đêm định mệnh. Liên tiếp chuyện kinh hoàng bất ngờ đẩy anh vào giữa vòng xoáy hỗn loạn.','Zach Cregger','Austin Abrams, Zach Cherry, Kali Reis, Paul Walter Hauser, Johnno Wilson',94,'2026-09-18','2026-11-17','T18','posters/vung-dat-quy-du-2026.webp','https://www.youtube.com/watch?v=2flaT7JNc-U','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(20,'Lên Hương','len-huong','Một bà chủ của trại hòm ế ẩm và một thanh niên cần tiền trang trải cuộc sống đã vô tình mắc vào một “giao kèo định mệnh\".\nMột người cố giữ nghề, một người cố cứu mạng người mẹ đang bệnh nặng, mở ra bí mật về món nợ đã chôn vùi suốt nhiều năm.','Tấn Hoàng Thông, Khương Ngọc','Hồng Đào, Võ Tấn Phát, Tuyết Thu, Hồng Vân, Lê Hạ Anh, Nguyễn Quốc Khánh',121,'2026-09-14','2026-11-10','T16','posters/len-huong.webp','https://www.youtube.com/watch?v=VcAHmTOK-TI','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(21,'Bát Tiên Truy Tìm Lưu Ly Đăng','bat-tien-truy-tim-luu-ly-dang','Tám phàm nhân với tám giấc mộng đổi đời đã thực hiện một phi vụ liều lĩnh: đột nhập chốn Bồng Lai để đánh cắp bảo vật. Những tưởng trộm được bảo vật của Tam Tinh là có thể giúp họ một bước đổi vận, nhưng cả nhóm lại vô tình bị cuốn vào âm mưu đen tối chốn Thiên Đình. Khi bí mật dần hé lộ và kẻ thù thực sự xuất hiện, tám con người \"chẳng có thần thông cũng không mang pháp lực\" buộc phải đối đầu với vị thần tiên đầy quyền năng. Từ những kẻ vô danh chỉ muốn thay đổi số phận, họ bất đắc dĩ trở thành những người nắm giữ vận mệnh Tam Giới. Hành trình hài hước về những con người bé nhỏ dám làm nên chuyện lớn đã đưa Bát Tiên! Truy Tìm Lưu Ly Đăng trở thành phim hoạt hình Trung Quốc có doanh thu cao nhất năm 2026 và lọt top 4 phim hoạt hình có doanh thu phòng vé cao nhất mọi thời đại.','Mu Zhengyang','Hao Chen, 李绍哲, 立冬, Huang Guo, Dong Tianyi, Yu Pengli, Huang Yushuo, Zhang Yunqi, Deng Xiansen, Cao Zhishan, Joseph, Ling Qi, Han Yuze, Zhang Tianyu, Zhang Ji, Liang Sheng, Yao Yumo, Wang Zicheng, Chang Huanyu, Yizhou, Yu Yingjie',144,'2026-09-11','2026-11-24','P','posters/bat-tien-truy-tim-luu-ly-dang.webp','https://www.youtube.com/watch?v=5N8jvHVtlko','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(22,'Hộ Linh Tráng Sĩ: Bí Ẩn Mộ Vua Đinh (Rút Gọn)','ho-linh-trang-si-bi-an-mo-vua-dinh-rut-gon','Bộ phim huyền sử về hành trình của 7 Hộ Linh Tráng Sĩ trong nhiệm vụ cuối cùng Tiên Đế giao. Họ phải chạy đua với thời gian, đối đầu với các thế lực thù địch, đưa 99 quan tài của Đinh Tiên Hoàng Đế đi theo 7 hướng khác nhau, đánh lừa kẻ thù đang rắp tâm phá hoại lăng mộ - nơi được tin là cội nguồn vượng khí của dân tộc. Nhưng điều gì ẩn giấu trong những chiếc quan tài ấy? Liệu đó chỉ là thi hài của vị Hoàng đế đầu tiên, hay còn một bí mật lớn lao hơn mà 7 Tráng sĩ đã thề chết để bảo vệ?','Nguyễn Phan Quang Bình','Quách Ngọc Ngoan, Johnny Trí Nguyễn, Tuấn Trần, Trần Thiên Tú, Đỗ Thị Hải Yến',135,'2026-08-28','2026-11-24','T13','posters/ho-linh-trang-si-bi-an-mo-vua-dinh-rut-gon.webp','https://www.youtube.com/watch?v=UvRjnWJ7PoM','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(23,'Chiikawa: Bí Mật Đảo Người Cá','chiikawa-bi-mat-dao-nguoi-ca','Bộ ba Chiikawa, Hachiware và Usagi nhận được một lời mời tham gia chuyến đi đến hòn đảo đặc biệt với những phần thưởng và đồ ăn miễn phí. Cả nhóm cùng lên đường phiêu lưu ra đảo cùng với nhân vật Rakko – người vốn mang lòng hoài nghi về những lời hứa hẹn trong tờ rơi. Hòn đảo tưởng chừng vui vẻ này lại ẩn chứa nhiều điều kỳ bí và bí mật lâu đời liên quan đến người cá.','Kei Oikawa','Haruka Aoki, Makoto Tanaka, Ari Ozawa, Yuka Iguchi, Takayuki Asai, Yuma Uchida, Miyuri Shimabukuro, Momo Harumi, Tsuguo Mogami, Minori Suzuki, Momoka Terasawa, Sayumi Suzushiro, Saeko Oki, Ayaka Nanase',99,'2026-08-28','2026-11-24','P','posters/chiikawa-bi-mat-dao-nguoi-ca.webp','https://www.youtube.com/watch?v=8LJm14u1o-E','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(24,'Tàu Buôn Người','tau-buon-nguoi','Mutiny (Tàu Buôn Người) kể về Cole Reed do Jason Statham thủ vai, sau khi tận mắt chứng kiến ông chủ tỷ phú của mình bị sát hại và bản thân trở thành kẻ thế thân bị vu oan, Cole Reed (Jason Statham) đã đột nhập lên một con tàu chở hàng để bắt đầu hành trình truy tìm sự thật và trả thù cho vị sếp cũ. Tuy nhiên, chuyến đi đơn độc này lại đẩy anh vào nguy hiểm khi Cole vô tình bóc trần một âm mưu quốc tế quy mô và cực kỳ nguy hiểm.','Jean-François Richet','Jason Statham, Annabelle Wallis, Roland Møller, Arnas Fedaravičius, Adrian Lester, Jason Wong, Ramon Tikaram, Lee Charles, Ben Cartwright, Chaneil Kular, Steven Blades, Tom Christian, Rumi Sutton, Jessica Wai Sum Tong, Caroline Glass',95,'2026-08-28','2026-11-17','T18','posters/tau-buon-nguoi.webp','https://www.youtube.com/watch?v=SJElX8y4Joc','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(25,'Shin Cậu Bé Bút Chì: Kỳ Kỳ Quái Quái Kỳ Nghỉ Yêu Quái Của Tớ','shin-cau-be-but-chi-ky-ky-quai-quai-ky-nghi-yeu-quai-cua-to','Lấy bối cảnh mùa hè tại Akita, bộ phim theo chân Shin và gia đình Nohara trong chuyến về quê đầy háo hức. Tuy nhiên, một sự kiện kỳ lạ đã đưa cả gia đình lạc vào Xứ sở Yêu quái bí ẩn – nơi con người không được phép đặt chân tới.\n\nTại đây, Shin và gia đình phải đối mặt với những thử thách chưa từng có, đồng thời gặp gỡ hàng loạt yêu quái độc đáo, hài hước và đáng yêu. Với sự kết hợp giữa yếu tố phiêu lưu, kỳ ảo, hài hước đặc trưng của Shin-chan cùng những thông điệp gia đình ấm áp, bộ phim hứa hẹn mang đến một hành trình giải trí hấp dẫn cho khán giả ở mọi lứa tuổi trong mùa hè này.','Masaki Watanabe','Yumiko Kobayashi, Miki Narahashi, Toshiyuki Morikawa, Satomi Kourogi',101,'2026-08-21','2026-11-24','P','posters/shin-cau-be-but-chi-ky-ky-quai-quai-ky-nghi-yeu-quai-cua-to.webp','https://www.youtube.com/watch?v=jBFzXQQ4aR4','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(26,'The Odyssey','the-odyssey','Bộ phim tiếp theo của Christopher Nolan, The Odyssey, là một sử thi hành động mang màu sắc thần thoại, được quay tại nhiều địa điểm trên khắp thế giới bằng công nghệ phim IMAX® hoàn toàn mới.\n\nPhim The Odyssey theo chân Odysseus trong hành trình trở về nhà sau cuộc chiến thành Troy, tràn ngập thử thách như cuộc chạm trán của ông với Polyphemus, các nàng tiên cá, Circe và kết thúc bằng cuộc đoàn tụ với vợ mình, Penelope.','Christopher Nolan','Matt Damon, Tom Holland, Zendaya, Anne Hathaway, Lupita Nyong\'o, Robert Pattinson, Benny Safdie, Charlize Theron, Jon Bernthal, John Leguizamo, Himesh Patel, Elliot Page, Bill Irwin, Samantha Morton, Jesse Garcia, Will Yun Lee, Rafi Gavron',173,'2026-07-17','2026-11-24','T16','posters/the-odyssey.webp','https://www.youtube.com/watch?v=vRYJwJIdpjs','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(27,'Gia Đình x Điệp Viên Mã: Trắng','gia-dinh-x-diep-vien-ma-trang','Trong phần phim điện ảnh lần này, sau khi nhận được yêu cầu thay thế mình trong Chiến dịch Strix, Loid Forger quyết định giúp con gái Anya chiến thắng trong cuộc thi nấu ăn tại Học viện Eden bằng cách nấu bữa ăn yêu thích của hiệu trưởng để tránh bị thay thế khỏi nhiệm vụ mật. Nhưng từ đây, gia đình Forger phát hiện ra bí mật kinh hoàng ảnh hưởng đến hòa bình thế giới.','Takashi Katagiri','Shunsuke Takeuchi, Banjo Ginga, Kento Kaku, Tomoya Nakamura, Kenichirou Matsuda, Saori Hayami, Atsumi Tanezaki, Takuya Eguchi',110,'2024-02-10','2026-11-17','T13','posters/spy-family-code-white.webp','https://www.youtube.com/watch?v=iMSaQm7lfOo','now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(28,'Ngọn Đồi Hoa Hồng Anh','ngon-doi-hoa-hong-anh','Umi Matsuzaki là chị cả trong gia đình có ba anh em, sống tại nhà trọ Coquelicot Manor và học năm hai trung học. Mỗi sáng cô đều kéo cờ tưởng niệm người cha đã mất trong chiến tranh. Ở trường, tranh cãi nổ ra về việc giữ hay phá dỡ khu “Latin Quarter” lịch sử. Umi tham gia cùng Shun Kazama trong nỗ lực bảo tồn nơi này và cả hai dần trở nên thân thiết. Tuy nhiên, một bức ảnh bất ngờ khiến họ nghi ngờ có thể là anh em ruột…','Goro Miyazaki','Masami Nagasawa, Junichi Okada, Keiko Takeshita, Yuriko Ishida, Rumi Hiiragi, Jun Fubuki, Takashi Naitô, Shunsuke Kazama, Nao Ōmori, Teruyuki Kagawa, Haruka Shiraishi, Tsubasa Kobayashi, Aoi Teshima, Goro Miyazaki',91,'2026-10-27','2026-12-22','P','posters/from-up-on-poppy-hill.webp',NULL,'now_showing','2026-10-27 13:05:06','2026-10-27 13:05:06',NULL),(29,'SEVENTEEN World Tour [New_]','seventeen-world-tour-new','SEVENTEEN mang chuyến lưu diễn thế giới New_ đến khán giả tại rạp. Đây là tour diễn đánh dấu chặng đường mới của nhóm sau cột mốc 10 năm hoạt động.','Yum Tae-hwan',